// ===================== insertion-ordered dict =====================
// Python dicts preserve insertion order; std::map sorts by key. This drop-in
// container behaves like a mapping while iterating/printing in the order the
// keys were first inserted.
template <class K, class V>
struct dict {
    std::vector<std::pair<K, V>> items;
    using value_type = std::pair<K, V>;
    using key_type = K;
    using mapped_type = V;
    using iterator = typename std::vector<std::pair<K, V>>::iterator;
    using const_iterator = typename std::vector<std::pair<K, V>>::const_iterator;

    dict() = default;
    dict(std::initializer_list<std::pair<K, V>> il) {
        for (const auto& p : il) (*this)[p.first] = p.second;
    }

    iterator begin() { return items.begin(); }
    iterator end() { return items.end(); }
    const_iterator begin() const { return items.begin(); }
    const_iterator end() const { return items.end(); }

    std::size_t size() const { return items.size(); }
    bool empty() const { return items.empty(); }

    iterator find(const K& k) {
        for (auto it = items.begin(); it != items.end(); ++it)
            if (it->first == k) return it;
        return items.end();
    }
    const_iterator find(const K& k) const {
        for (auto it = items.begin(); it != items.end(); ++it)
            if (it->first == k) return it;
        return items.end();
    }
    std::size_t count(const K& k) const { return find(k) == items.end() ? 0 : 1; }

    V& operator[](const K& k) {
        for (auto& p : items)
            if (p.first == k) return p.second;
        items.push_back(std::make_pair(k, V{}));
        return items.back().second;
    }

    std::vector<K> keys() const {
        std::vector<K> r;
        r.reserve(items.size());
        for (const auto& p : items) r.push_back(p.first);
        return r;
    }
    std::vector<V> values() const {
        std::vector<V> r;
        r.reserve(items.size());
        for (const auto& p : items) r.push_back(p.second);
        return r;
    }
};

template <class K, class V>
std::string str(const dict<K, V>& m);
