// ---- uniform "iterable" view ----------------------------------------------
// In Python a str is a sequence of exactly its characters.  In C++ a string
// *literal* is a `const char[N]` array whose trailing '\0' would be iterated as
// an extra element (so `enumerate("abc")` yielded 4 entries).  `seq()` maps any
// char array / char pointer to a std::string and leaves every other container
// untouched (returned by const reference).
template <class C>
decltype(auto) seq(const C& c) {
    using D = std::remove_cv_t<std::remove_reference_t<C>>;
    if constexpr (std::is_pointer_v<D> &&
                  std::is_same_v<std::remove_cv_t<std::remove_pointer_t<D>>, char>) {
        return std::string(c);
    } else if constexpr (std::is_array_v<D> &&
                         std::is_same_v<std::remove_cv_t<std::remove_extent_t<D>>, char>) {
        return std::string(c);
    } else {
        return (c);
    }
}
template <class C>
using seq_t = std::remove_cv_t<std::remove_reference_t<decltype(seq(std::declval<const C&>()))>>;
// Element type of any iterable, including arrays and string literals.
template <class C>
using elem_t =
    std::remove_cv_t<std::remove_reference_t<decltype(*std::begin(std::declval<const seq_t<C>&>()))>>;

template <class T>
inline long long len(const T& c) {
    return static_cast<long long>(seq(c).size());
}

// membership tests
inline bool contains(const std::string& s, const std::string& sub) {
    return s.find(sub) != std::string::npos;
}
inline bool contains(const std::string& s, const char* sub) { return s.find(sub) != std::string::npos; }
inline bool contains(const std::string& s, char c) { return s.find(c) != std::string::npos; }
template <class T, class V>
inline bool contains(const std::vector<T>& c, const V& v) {
    return std::find(c.begin(), c.end(), v) != c.end();
}
template <class K, class V, class Q>
inline bool contains(const std::map<K, V>& m, const Q& q) {
    return m.find(q) != m.end();
}
template <class K, class V, class Q>
inline bool contains(const dict<K, V>& m, const Q& q) {
    return m.find(q) != m.end();
}
template <class T, class Q>
inline bool contains(const std::set<T>& s, const Q& q) {
    return s.find(q) != s.end();
}
template <class A, class B>
inline bool contains(const std::pair<A, B>& p, const A& k) {
    return p.first == k;
}

// ===================== indexing =====================
template <class C>
decltype(auto) item(C&& c, long long i) {
    long long n = static_cast<long long>(c.size());
    if (i < 0) i += n;
    if (i < 0 || i >= n) throw IndexError("index out of range");
    using V = std::remove_cv_t<std::remove_reference_t<decltype(c[static_cast<std::size_t>(0)])>>;
    if constexpr (std::is_same_v<V, char>)
        return std::string(1, c[static_cast<std::size_t>(i)]);
    else
        return c[static_cast<std::size_t>(i)];
}

template <class M, class K>
decltype(auto) dget(M&& m, const K& k) {
    auto it = m.find(k);
    if (it == m.end()) throw KeyError("key not found");
    return (it->second);  // parenthesised: return the stored lvalue, not a copy
}

// Python iterates a str as a sequence of 1-character strings.
inline std::vector<std::string> py_chars(const std::string& s) {
    std::vector<std::string> r;
    r.reserve(s.size());
    for (char c : s) r.emplace_back(1, c);
    return r;
}

// slicing (NONE_LL means "omitted")
template <class T>
std::vector<T> slice(const std::vector<T>& v, long long lo, long long hi) {
    long long n = static_cast<long long>(v.size());
    if (lo == NONE_LL) lo = 0;
    if (hi == NONE_LL) hi = n;
    if (lo < 0) lo += n;
    if (hi < 0) hi += n;
    lo = std::max<long long>(0, std::min(lo, n));
    hi = std::max<long long>(0, std::min(hi, n));
    if (hi < lo) hi = lo;
    return std::vector<T>(v.begin() + lo, v.begin() + hi);
}
inline std::string slice(const std::string& s, long long lo, long long hi) {
    long long n = static_cast<long long>(s.size());
    if (lo == NONE_LL) lo = 0;
    if (hi == NONE_LL) hi = n;
    if (lo < 0) lo += n;
    if (hi < 0) hi += n;
    lo = std::max<long long>(0, std::min(lo, n));
    hi = std::max<long long>(0, std::min(hi, n));
    if (hi < lo) hi = lo;
    return s.substr(static_cast<std::size_t>(lo), static_cast<std::size_t>(hi - lo));
}
template <class T>
std::vector<T> slice_step(const std::vector<T>& v, long long lo, long long hi, long long step) {
    long long n = static_cast<long long>(v.size());
    if (step == 0) throw ValueError("slice step cannot be zero");
    if (step > 0) {
        if (lo == NONE_LL) lo = 0;
        if (hi == NONE_LL) hi = n;
        if (lo < 0) lo += n;
        if (hi < 0) hi += n;
        lo = std::max<long long>(0, std::min(lo, n));
        hi = std::max<long long>(0, std::min(hi, n));
        std::vector<T> r;
        for (long long i = lo; i < hi; i += step) r.push_back(v[static_cast<std::size_t>(i)]);
        return r;
    }
    if (lo == NONE_LL) lo = n - 1;
    if (hi == NONE_LL) hi = -n - 1;
    if (lo < 0) lo += n;
    if (hi < 0) hi += n;
    lo = std::max<long long>(-1, std::min(lo, n - 1));
    hi = std::max<long long>(-1, std::min(hi, n - 1));
    std::vector<T> r;
    for (long long i = lo; i > hi; i += step) r.push_back(v[static_cast<std::size_t>(i)]);
    return r;
}
inline std::string slice_step(const std::string& s, long long lo, long long hi, long long step) {
    std::vector<char> v(s.begin(), s.end());
    auto r = slice_step(v, lo, hi, step);
    return std::string(r.begin(), r.end());
}

// ===================== numeric semantics =====================
template <class A, class B,
          class = std::enable_if_t<std::is_arithmetic_v<A> && std::is_arithmetic_v<B>>>
inline double truediv(A a, B b) {
    double db = static_cast<double>(b);
    if (db == 0.0) throw ZeroDivisionError("division by zero");
    return static_cast<double>(a) / db;
}

template <class A, class B,
          class = std::enable_if_t<std::is_arithmetic_v<A> && std::is_arithmetic_v<B>>>
inline auto floordiv(A a, B b) {
    double db = static_cast<double>(b);
    if (db == 0.0) throw ZeroDivisionError("integer division or modulo by zero");
    double r = std::floor(static_cast<double>(a) / db);
    if constexpr (std::is_integral_v<A> && std::is_integral_v<B>)
        return static_cast<long long>(r);
    else
        return r;
}

template <class A, class B,
          class = std::enable_if_t<std::is_arithmetic_v<A> && std::is_arithmetic_v<B>>>
inline auto pymod(A a, B b) {
    double db = static_cast<double>(b);
    if (db == 0.0) throw ZeroDivisionError("integer division or modulo by zero");
    if constexpr (std::is_integral_v<A> && std::is_integral_v<B>) {
        long long la = static_cast<long long>(a), lb = static_cast<long long>(b);
        long long r = la % lb;
        if (r != 0 && ((r < 0) != (lb < 0))) r += lb;
        return r;
    } else {
        double r = std::fmod(static_cast<double>(a), db);
        if (r != 0 && ((r < 0) != (db < 0))) r += db;
        return r;
    }
}

template <class A, class B,
          class = std::enable_if_t<std::is_arithmetic_v<A> && std::is_arithmetic_v<B>>>
inline auto power(A a, B b) {
    if constexpr (std::is_integral_v<A> && std::is_integral_v<B>) {
        long long e = static_cast<long long>(b);
        if (e >= 0) {
            long long result = 1, base = static_cast<long long>(a);
            while (e) {
                if (e & 1) result *= base;
                base *= base;
                e >>= 1;
            }
            return result;
        }
        return static_cast<long long>(static_cast<double>(0));
    } else {
        return std::pow(static_cast<double>(a), static_cast<double>(b));
    }
}

inline long long int_div_floor(long long a, long long b) {
    if (b == 0) throw ZeroDivisionError("integer division or modulo by zero");
    long long q = a / b;
    if ((a % b != 0) && ((a < 0) != (b < 0))) --q;
    return q;
}

// ===================== conversions =====================
inline long long to_int(long long v) { return v; }
inline long long to_int(int v) { return v; }
inline long long to_int(bool v) { return v ? 1 : 0; }
inline long long to_int(char v) { return v; }
inline long long to_int(double v) { return static_cast<long long>(std::trunc(v)); }
inline long long to_int(const std::string& s) {
    std::string t;
    for (char c : s)
        if (!std::isspace(static_cast<unsigned char>(c))) t += c;
    if (t.empty()) throw ValueError("invalid literal for int()");
    std::size_t used = 0;
    long long v = 0;
    try {
        v = std::stoll(t, &used, 10);
    } catch (...) {
        throw ValueError("invalid literal for int(): " + s);
    }
    if (used != t.size()) throw ValueError("invalid literal for int(): " + s);
    return v;
}
inline long long to_int(const char* s) { return to_int(std::string(s)); }

inline double to_float(double v) { return v; }
inline double to_float(long long v) { return static_cast<double>(v); }
inline double to_float(const std::string& s) {
    std::string t;
    for (char c : s)
        if (!std::isspace(static_cast<unsigned char>(c))) t += c;
    if (t.empty()) throw ValueError("could not convert string to float: " + s);
    std::size_t used = 0;
    double v = 0;
    try {
        v = std::stod(t, &used);
    } catch (...) {
        throw ValueError("could not convert string to float: " + s);
    }
    if (used != t.size()) throw ValueError("could not convert string to float: " + s);
    return v;
}
inline double to_float(const char* s) { return to_float(std::string(s)); }

inline bool to_bool(bool v) { return v; }
inline bool to_bool(long long v) { return v != 0; }
inline bool to_bool(int v) { return v != 0; }
inline bool to_bool(double v) { return v != 0.0; }
inline bool to_bool(const std::string& s) { return !s.empty(); }
inline bool to_bool(const char* s) { return s && *s; }
template <class T>
inline bool to_bool(const std::vector<T>& v) { return !v.empty(); }
template <class K, class V>
inline bool to_bool(const std::map<K, V>& m) { return !m.empty(); }
template <class K, class V>
inline bool to_bool(const dict<K, V>& m) { return !m.empty(); }

// ===================== math / builtins =====================
inline long long py_abs(long long v) { return v < 0 ? -v : v; }
inline long long py_abs(int v) { return v < 0 ? -static_cast<long long>(v) : v; }
inline double py_abs(double v) { return std::fabs(v); }

inline long long py_round(double v) {
    double r = std::nearbyint(v);  // banker's rounding, like Python
    return static_cast<long long>(r);
}
inline double py_round(double v, long long digits) {
    double f = std::pow(10.0, static_cast<double>(digits));
    return std::nearbyint(v * f) / f;
}

template <class C>
auto py_min(const C& c) {
    const auto& cc = seq(c);
    if (cc.begin() == cc.end()) throw ValueError("min() arg is an empty sequence");
    return *std::min_element(cc.begin(), cc.end());
}
template <class C>
auto py_max(const C& c) {
    const auto& cc = seq(c);
    if (cc.begin() == cc.end()) throw ValueError("max() arg is an empty sequence");
    return *std::max_element(cc.begin(), cc.end());
}

// min(a, b, ...) / max(a, b, ...) with possibly different numeric types:
// std::min/std::max would fail to deduce a common type.
template <class First, class... Rest>
auto py_min_of(First first, Rest... rest) {
    using C = std::common_type_t<First, Rest..., First>;
    C acc = static_cast<C>(first);
    for (const C& v : std::initializer_list<C>{static_cast<C>(rest)...})
        if (v < acc) acc = v;
    return acc;
}
template <class First, class... Rest>
auto py_max_of(First first, Rest... rest) {
    using C = std::common_type_t<First, Rest..., First>;
    C acc = static_cast<C>(first);
    for (const C& v : std::initializer_list<C>{static_cast<C>(rest)...})
        if (acc < v) acc = v;
    return acc;
}

template <class C>
auto py_sum(const C& c) {
    const auto& cc = seq(c);
    elem_t<C> acc{};
    for (const auto& e : cc) acc += e;
    return acc;
}
template <class C, class T>
auto py_sum(const C& c, T start) {
    T acc = start;
    for (const auto& e : seq(c)) acc += e;
    return acc;
}

template <class C>
auto py_sorted(const C& c) {
    const auto& cc = seq(c);
    std::vector<elem_t<C>> v(std::begin(cc), std::end(cc));
    std::sort(v.begin(), v.end());
    return v;
}
template <class C, class Key>
auto py_sorted(const C& c, Key key, bool reverse = false) {
    const auto& cc = seq(c);
    std::vector<elem_t<C>> v(std::begin(cc), std::end(cc));
    if (reverse)
        std::sort(v.begin(), v.end(), [&](const auto& a, const auto& b) { return key(a) > key(b); });
    else
        std::sort(v.begin(), v.end(), [&](const auto& a, const auto& b) { return key(a) < key(b); });
    return v;
}
template <class C>
auto py_sorted_rev(const C& c) {
    const auto& cc = seq(c);
    std::vector<elem_t<C>> v(std::begin(cc), std::end(cc));
    std::sort(v.begin(), v.end(), std::greater<>());
    return v;
}

template <class C, class Key>
auto py_sort_by(C& c, Key key, bool reverse = false) {
    if (reverse)
        std::stable_sort(c.begin(), c.end(), [&](const auto& a, const auto& b) { return key(a) > key(b); });
    else
        std::stable_sort(c.begin(), c.end(), [&](const auto& a, const auto& b) { return key(a) < key(b); });
}

template <class C>
auto enumerate(const C& c) {
    const auto& cc = seq(c);
    std::vector<std::pair<long long, elem_t<C>>> r;
    long long i = 0;
    for (const auto& e : cc) r.emplace_back(i++, e);
    return r;
}
template <class C>
auto enumerate_from(const C& c, long long start) {
    const auto& cc = seq(c);
    std::vector<std::pair<long long, elem_t<C>>> r;
    long long i = start;
    for (const auto& e : cc) r.emplace_back(i++, e);
    return r;
}

template <class K, class V>
std::vector<V> map_values(const std::map<K, V>& m) {
    std::vector<V> r;
    for (const auto& kv : m) r.push_back(kv.second);
    return r;
}
template <class K, class V>
std::vector<V> map_values(const dict<K, V>& m) {
    std::vector<V> r;
    r.reserve(m.items.size());
    for (const auto& kv : m) r.push_back(kv.second);
    return r;
}
// subscript store:  m[k] = v  (works for std::map and py::dict)
template <class M, class K, class V>
void dset(M& m, const K& k, const V& v) {
    m[k] = v;
}
template <class M, class K>
auto dget_or(const M& m, const K& k) {
    auto it = m.find(k);
    if (it == m.end()) throw KeyError("key not found");
    return it->second;
}
template <class M, class K, class D>
auto dget_or(const M& m, const K& k, const D& def) {
    auto it = m.find(k);
    return it == m.end() ? static_cast<typename M::mapped_type>(def) : it->second;
}

template <class C>
bool any_of(const C& c) {
    for (const auto& e : seq(c))
        if (to_bool(e)) return true;
    return false;
}
template <class C>
bool all_of(const C& c) {
    for (const auto& e : seq(c))
        if (!to_bool(e)) return false;
    return true;
}

// map(f, xs) / filter(f, xs) -- return lists so they can be printed/iterated.
template <class F, class C>
auto py_map(F f, const C& c) {
    const auto& cc = seq(c);
    using R = std::remove_cv_t<std::remove_reference_t<decltype(f(*std::begin(cc)))>>;
    std::vector<R> r;
    r.reserve(cc.size());
    for (const auto& e : cc) r.push_back(f(e));
    return r;
}
template <class F, class C>
auto py_filter(F f, const C& c) {
    const auto& cc = seq(c);
    using R = elem_t<C>;
    std::vector<R> r;
    for (const auto& e : cc)
        if (to_bool(f(e))) r.push_back(e);
    return r;
}
template <class C>
auto py_reversed(const C& c) {
    const auto& cc = seq(c);
    std::vector<elem_t<C>> r(cc.rbegin(), cc.rend());
    return r;
}
inline std::string py_reversed(const std::string& s) {
    return std::string(s.rbegin(), s.rend());
}

inline std::mt19937_64& rng();

inline double uniform(double a, double b) {
    return std::uniform_real_distribution<double>(a, b)(rng());
}
inline double time_now() {
    using namespace std::chrono;
    return duration<double>(system_clock::now().time_since_epoch()).count();
}

template <class A, class B>
auto zip2(const A& a, const B& b) {
    const auto& aa = seq(a);
    const auto& bb = seq(b);
    std::vector<elem_t<A>> va(std::begin(aa), std::end(aa));
    std::vector<elem_t<B>> vb(std::begin(bb), std::end(bb));
    std::vector<std::pair<elem_t<A>, elem_t<B>>> r;
    std::size_t n = std::min(va.size(), vb.size());
    for (std::size_t i = 0; i < n; ++i) r.emplace_back(va[i], vb[i]);
    return r;
}

inline std::vector<long long> xrange(long long start, long long stop, long long step) {
    if (step == 0) throw ValueError("range() arg 3 must not be zero");
    std::vector<long long> r;
    if (step > 0)
        for (long long i = start; i < stop; i += step) r.push_back(i);
    else
        for (long long i = start; i > stop; i += step) r.push_back(i);
    return r;
}
inline std::vector<long long> xrange(long long stop) { return xrange(0, stop, 1); }
inline std::vector<long long> xrange(long long start, long long stop) { return xrange(start, stop, 1); }

template <class T>
std::vector<T> to_list(const std::vector<T>& v) { return v; }
inline std::vector<std::string> to_list(const std::string& s) {
    std::vector<std::string> r;
    for (char c : s) r.push_back(std::string(1, c));
    return r;
}
template <class K, class V>
std::vector<K> to_list_keys(const std::map<K, V>& m) {
    std::vector<K> r;
    for (const auto& kv : m) r.push_back(kv.first);
    return r;
}
