// ---- set algebra (Python's | & - on sets) ---------------------------------
template <class A, class B>
auto set_union(const A& a, const B& b) {
    std::set<elem_t<A>> r(a.begin(), a.end());
    for (const auto& e : b) r.insert(e);
    return r;
}
template <class A, class B>
auto set_inter(const A& a, const B& b) {
    std::set<elem_t<A>> r;
    for (const auto& e : a)
        if (b.count(e)) r.insert(e);
    return r;
}
template <class A, class B>
auto set_diff(const A& a, const B& b) {
    std::set<elem_t<A>> r;
    for (const auto& e : a)
        if (!b.count(e)) r.insert(e);
    return r;
}
template <class A, class B>
bool set_subset(const A& a, const B& b) {
    for (const auto& e : a)
        if (!b.count(e)) return false;
    return true;
}
template <class A>
void set_remove(A& a, const elem_t<A>& x) {
    auto it = a.find(x);
    if (it == a.end()) throw KeyError("element not found");
    a.erase(it);
}

inline std::vector<std::string> split(const std::string& s, const std::string& sep = "") {
    std::vector<std::string> r;
    if (sep.empty()) {
        std::size_t i = 0;
        while (i < s.size()) {
            while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) i++;
            std::size_t j = i;
            while (j < s.size() && !std::isspace(static_cast<unsigned char>(s[j]))) j++;
            if (j > i) r.push_back(s.substr(i, j - i));
            i = j;
        }
        return r;
    }
    std::size_t pos = 0;
    while (true) {
        std::size_t k = s.find(sep, pos);
        if (k == std::string::npos) {
            r.push_back(s.substr(pos));
            break;
        }
        r.push_back(s.substr(pos, k - pos));
        pos = k + sep.size();
    }
    return r;
}
inline std::vector<std::string> split(const std::string& s, const std::string& sep, long long maxsplit) {
    std::vector<std::string> r;
    if (maxsplit < 0) return split(s, sep);
    if (sep.empty()) {
        std::size_t i = 0;
        long long done = 0;
        while (i < s.size()) {
            while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) i++;
            if (i >= s.size()) break;
            if (done == maxsplit) {
                r.push_back(s.substr(i));
                break;
            }
            std::size_t j = i;
            while (j < s.size() && !std::isspace(static_cast<unsigned char>(s[j]))) j++;
            r.push_back(s.substr(i, j - i));
            i = j;
            done++;
        }
        return r;
    }
    std::size_t pos = 0;
    long long done = 0;
    while (done < maxsplit) {
        std::size_t k = s.find(sep, pos);
        if (k == std::string::npos) break;
        r.push_back(s.substr(pos, k - pos));
        pos = k + sep.size();
        done++;
    }
    r.push_back(s.substr(pos));
    return r;
}

template <class C>
std::string join(const std::string& sep, const C& parts) {
    std::string r;
    bool first = true;
    for (const auto& p : parts) {
        if (!first) r += sep;
        first = false;
        r += str(p);
    }
    return r;
}

inline std::string upper(std::string s) {
    for (auto& c : s) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    return s;
}
inline std::string lower(std::string s) {
    for (auto& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}
inline std::string strip(const std::string& s, const std::string& chars = " \t\n\r\f\v") {
    std::size_t a = s.find_first_not_of(chars);
    if (a == std::string::npos) return "";
    std::size_t b = s.find_last_not_of(chars);
    return s.substr(a, b - a + 1);
}
inline std::string lstrip(const std::string& s, const std::string& chars = " \t\n\r\f\v") {
    std::size_t a = s.find_first_not_of(chars);
    return a == std::string::npos ? "" : s.substr(a);
}
inline std::string rstrip(const std::string& s, const std::string& chars = " \t\n\r\f\v") {
    std::size_t b = s.find_last_not_of(chars);
    return b == std::string::npos ? "" : s.substr(0, b + 1);
}
inline std::string replace(const std::string& s, const std::string& from, const std::string& to) {
    if (from.empty()) return s;
    std::string r;
    std::size_t pos = 0;
    while (true) {
        std::size_t k = s.find(from, pos);
        if (k == std::string::npos) {
            r += s.substr(pos);
            break;
        }
        r += s.substr(pos, k - pos);
        r += to;
        pos = k + from.size();
    }
    return r;
}
inline bool startswith(const std::string& s, const std::string& p) {
    return s.size() >= p.size() && s.compare(0, p.size(), p) == 0;
}
inline bool endswith(const std::string& s, const std::string& p) {
    return s.size() >= p.size() && s.compare(s.size() - p.size(), p.size(), p) == 0;
}
inline long long find(const std::string& s, const std::string& sub) {
    std::size_t k = s.find(sub);
    return k == std::string::npos ? -1 : static_cast<long long>(k);
}
inline long long rfind(const std::string& s, const std::string& sub) {
    std::size_t k = s.rfind(sub);
    return k == std::string::npos ? -1 : static_cast<long long>(k);
}
inline long long count_sub(const std::string& s, const std::string& sub) {
    if (sub.empty()) return static_cast<long long>(s.size()) + 1;
    long long n = 0;
    std::size_t pos = 0;
    while ((pos = s.find(sub, pos)) != std::string::npos) {
        n++;
        pos += sub.size();
    }
    return n;
}
inline std::string capitalize(std::string s) {
    if (s.empty()) return s;
    std::string r = lower(s);
    r[0] = static_cast<char>(std::toupper(static_cast<unsigned char>(r[0])));
    return r;
}
inline std::string title(std::string s) {
    bool start = true;
    for (auto& c : s) {
        if (std::isalpha(static_cast<unsigned char>(c))) {
            c = start ? static_cast<char>(std::toupper(static_cast<unsigned char>(c)))
                      : static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
            start = false;
        } else {
            start = true;
        }
    }
    return s;
}
inline std::string zfill(const std::string& s, long long width) {
    bool neg = !s.empty() && (s[0] == '-' || s[0] == '+');
    std::string body = neg ? s.substr(1) : s;
    while (static_cast<long long>(body.size()) < width - (neg ? 1 : 0)) body = "0" + body;
    return (neg ? std::string(1, s[0]) : "") + body;
}
inline std::string repeat(const std::string& s, long long n) {
    std::string r;
    for (long long i = 0; i < n; ++i) r += s;
    return r;
}
// list * int  /  int * list  (Python sequence repetition)
template <class T>
std::vector<T> repeat(const std::vector<T>& v, long long n) {
    std::vector<T> r;
    if (n <= 0) return r;
    r.reserve(v.size() * static_cast<std::size_t>(n));
    for (long long i = 0; i < n; ++i) r.insert(r.end(), v.begin(), v.end());
    return r;
}
inline std::string chr_of(long long c) { return std::string(1, static_cast<char>(c)); }
inline long long ord_of(const std::string& s) {
    if (s.empty()) throw ValueError("ord() expected a character");
    return static_cast<long long>(static_cast<unsigned char>(s[0]));
}
inline bool isdigit_(const std::string& s) {
    if (s.empty()) return false;
    for (char c : s)
        if (!std::isdigit(static_cast<unsigned char>(c))) return false;
    return true;
}
inline bool isalpha_(const std::string& s) {
    if (s.empty()) return false;
    for (char c : s)
        if (!std::isalpha(static_cast<unsigned char>(c))) return false;
    return true;
}
inline bool isspace_(const std::string& s) {
    if (s.empty()) return false;
    for (char c : s)
        if (!std::isspace(static_cast<unsigned char>(c))) return false;
    return true;
}
inline bool isalnum_(const std::string& s) {
    if (s.empty()) return false;
    for (char c : s)
        if (!std::isalnum(static_cast<unsigned char>(c))) return false;
    return true;
}

// list helpers
template <class T, class V>
void append(std::vector<T>& v, const V& x) {
    v.push_back(x);
}
template <class T, class C>
void extend(std::vector<T>& v, const C& xs) {
    v.insert(v.end(), xs.begin(), xs.end());
}
template <class T>
T pop(std::vector<T>& v) {
    if (v.empty()) throw IndexError("pop from empty list");
    T x = v.back();
    v.pop_back();
    return x;
}
template <class T>
T pop(std::vector<T>& v, long long i) {
    long long n = static_cast<long long>(v.size());
    if (i < 0) i += n;
    if (i < 0 || i >= n) throw IndexError("pop index out of range");
    T x = v[static_cast<std::size_t>(i)];
    v.erase(v.begin() + i);
    return x;
}
template <class T, class V>
void remove(std::vector<T>& v, const V& x) {
    auto it = std::find(v.begin(), v.end(), x);
    if (it == v.end()) throw ValueError("list.remove(x): x not in list");
    v.erase(it);
}
template <class T, class V>
long long index_of(const std::vector<T>& v, const V& x) {
    auto it = std::find(v.begin(), v.end(), x);
    if (it == v.end()) throw ValueError("value is not in list");
    return static_cast<long long>(it - v.begin());
}
template <class T, class V>
long long count_in(const std::vector<T>& v, const V& x) {
    long long n = 0;
    for (const auto& e : v)
        if (e == x) n++;
    return n;
}
template <class T>
void sort_inplace(std::vector<T>& v, bool reverse = false) {
    if (reverse)
        std::sort(v.begin(), v.end(), std::greater<>());
    else
        std::sort(v.begin(), v.end());
}
template <class T>
void reverse_inplace(std::vector<T>& v) {
    std::reverse(v.begin(), v.end());
}

template <class T>
std::vector<T> reversed(const std::vector<T>& v) {
    std::vector<T> r(v.rbegin(), v.rend());
    return r;
}
inline std::string reversed(const std::string& s) {
    return std::string(s.rbegin(), s.rend());
}

template <class T>
std::vector<T> concat(const std::vector<T>& a, const std::vector<T>& b) {
    std::vector<T> r = a;
    r.insert(r.end(), b.begin(), b.end());
    return r;
}

// Materialise a `*args` parameter pack into a vector.  An empty pack has no
// common type, so `long long` is always appended to anchor the result.
template <class... Ts>
auto make_list(Ts... vs) {
    using First = std::tuple_element_t<0, std::tuple<Ts..., long long>>;
    if constexpr (sizeof...(Ts) > 0 && !std::is_arithmetic_v<First>) {
        using E = std::common_type_t<Ts...>;
        return std::vector<E>{vs...};
    } else {
        using E = std::common_type_t<Ts..., long long>;
        return std::vector<E>{static_cast<E>(vs)...};
    }
}
