// ===================== format() for f-strings =====================
// Python format specification (mini-language):
//   [[fill]align][sign][#][0][width][grouping][.precision][type]
struct FmtSpec {
    char fill = ' ';
    char align = 0;      // '<' '>' '^'
    char sign = 0;       // '+' '-' ' '
    bool alt = false;    // '#'
    bool zero = false;   // leading '0'
    bool hasType = false;
    long long width = 0;
    char sep = 0;        // ',' or '_'
    int prec = -1;
    char type = 0;
};

inline FmtSpec parseFmtSpec(const std::string& spec) {
    FmtSpec sp;
    std::size_t i = 0, n = spec.size();
    if (n >= 2 && (spec[1] == '<' || spec[1] == '>' || spec[1] == '^')) {
        sp.fill = spec[0];
        sp.align = spec[1];
        i = 2;
    } else if (n >= 1 && (spec[0] == '<' || spec[0] == '>' || spec[0] == '^')) {
        sp.align = spec[0];
        i = 1;
    }
    if (i < n && (spec[i] == '+' || spec[i] == '-' || spec[i] == ' ')) sp.sign = spec[i++];
    if (i < n && spec[i] == '#') { sp.alt = true; ++i; }
    if (i < n && spec[i] == '0') { sp.zero = true; ++i; }
    while (i < n && std::isdigit(static_cast<unsigned char>(spec[i])))
        sp.width = sp.width * 10 + (spec[i++] - '0');
    if (i < n && (spec[i] == ',' || spec[i] == '_')) sp.sep = spec[i++];
    if (i < n && spec[i] == '.') {
        ++i;
        sp.prec = 0;
        while (i < n && std::isdigit(static_cast<unsigned char>(spec[i])))
            sp.prec = sp.prec * 10 + (spec[i++] - '0');
    }
    if (i < n) { sp.type = spec[i++]; sp.hasType = true; }
    return sp;
}

inline std::string fmtGroup(const std::string& digits, char sep) {
    std::string out;
    for (std::size_t k = 0; k < digits.size(); ++k) {
        if (k > 0 && (digits.size() - k) % 3 == 0) out += sep;
        out += digits[k];
    }
    return out;
}

inline std::string fmtPad(const std::string& body, const FmtSpec& sp, bool numeric) {
    if (sp.width <= static_cast<long long>(body.size())) return body;
    long long pad = sp.width - static_cast<long long>(body.size());
    char align = sp.align ? sp.align : (numeric ? '>' : '<');
    if (sp.zero && sp.align == 0) {
        std::string signPart, rest = body;
        if (!rest.empty() && (rest[0] == '-' || rest[0] == '+' || rest[0] == ' ')) {
            signPart = rest.substr(0, 1);
            rest.erase(0, 1);
        }
        std::string prefix;
        if (rest.size() >= 2 && rest[0] == '0' &&
            (rest[1] == 'x' || rest[1] == 'X' || rest[1] == 'o' || rest[1] == 'b' ||
             rest[1] == 'B')) {
            prefix = rest.substr(0, 2);
            rest.erase(0, 2);
        }
        return signPart + prefix + std::string(static_cast<std::size_t>(pad), '0') + rest;
    }
    std::string f(static_cast<std::size_t>(pad), sp.fill);
    if (align == '<') return body + f;
    if (align == '^') {
        long long l = pad / 2;
        return std::string(static_cast<std::size_t>(l), sp.fill) + body +
               std::string(static_cast<std::size_t>(pad - l), sp.fill);
    }
    return f + body;
}

inline std::string fmtApplySign(const std::string& mag, bool neg, const FmtSpec& sp) {
    if (neg) return "-" + mag;
    if (sp.sign == '+') return "+" + mag;
    if (sp.sign == ' ') return " " + mag;
    return mag;
}

inline std::string fmtDouble(double v, const FmtSpec& sp) {
    if (std::isnan(v)) return "nan";
    bool neg = std::signbit(v);
    if (std::isinf(v)) return fmtPad(fmtApplySign("inf", neg, sp), sp, true);
    char type = sp.hasType ? sp.type : 0;
    char buf[512];
    std::string mag;
    if (type == 'f' || type == 'F') {
        int prec = sp.prec < 0 ? 6 : sp.prec;
        std::snprintf(buf, sizeof(buf), "%.*f", prec, std::fabs(v));
        mag = buf;
    } else if (type == 'e' || type == 'E') {
        int prec = sp.prec < 0 ? 6 : sp.prec;
        std::snprintf(buf, sizeof(buf), "%.*e", prec, std::fabs(v));
        mag = buf;
        if (type == 'E')
            for (auto& c : mag) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    } else if (type == 'g' || type == 'G') {
        int prec = sp.prec < 0 ? 6 : sp.prec;
        std::snprintf(buf, sizeof(buf), "%.*g", prec, std::fabs(v));
        mag = buf;
        if (type == 'G')
            for (auto& c : mag) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    } else if (type == '%') {
        int prec = sp.prec < 0 ? 6 : sp.prec;
        std::snprintf(buf, sizeof(buf), "%.*f", prec, std::fabs(v) * 100.0);
        mag = std::string(buf) + "%";
    } else if (type == 'd') {
        mag = std::to_string(static_cast<long long>(std::fabs(v)));
    } else {
        std::string s = str(v);
        if (!s.empty() && (s[0] == '-' || s[0] == '+')) s.erase(0, 1);
        return fmtPad(fmtApplySign(s, neg, sp), sp, true);
    }
    return fmtPad(fmtApplySign(mag, neg, sp), sp, true);
}

// Integral formatting (d/x/X/o/b/c) plus float conversions on integral values.
template <class T>
std::string fmtIntegral(T v, const FmtSpec& sp) {
    char type = sp.hasType ? sp.type : 0;
    if (type == 'f' || type == 'F' || type == 'e' || type == 'E' || type == 'g' ||
        type == 'G' || type == '%')
        return fmtDouble(static_cast<double>(v), sp);

    bool neg = false;
    unsigned long long u = 0;
    if constexpr (std::is_signed_v<T>) {
        long long s = static_cast<long long>(v);
        neg = s < 0;
        u = neg ? static_cast<unsigned long long>(-(s + 1)) + 1ULL
                : static_cast<unsigned long long>(s);
    } else {
        u = static_cast<unsigned long long>(v);
    }

    if (type == 'c') {
        FmtSpec sp2 = sp;
        sp2.type = 0;
        return fmtPad(std::string(1, static_cast<char>(v)), sp2, false);
    }

    char base = (type == 'x' || type == 'X' || type == 'o' || type == 'b') ? type : 'd';
    std::string digits;
    if (base == 'd') {
        digits = std::to_string(u);
    } else if (base == 'x' || base == 'X') {
        char b[64];
        std::snprintf(b, sizeof(b), "%llx", u);
        digits = b;
        if (base == 'X')
            for (auto& c : digits) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    } else if (base == 'o') {
        char b[64];
        std::snprintf(b, sizeof(b), "%llo", u);
        digits = b;
    } else {
        if (u == 0) {
            digits = "0";
        } else {
            unsigned long long t = u;
            while (t) {
                digits += static_cast<char>('0' + (t & 1ULL));
                t >>= 1;
            }
            std::reverse(digits.begin(), digits.end());
        }
    }
    if (sp.sep) digits = fmtGroup(digits, sp.sep);

    std::string prefix;
    if (sp.alt) {
        if (base == 'x') prefix = "0x";
        else if (base == 'X') prefix = "0X";
        else if (base == 'o') prefix = "0o";
        else if (base == 'b') prefix = "0b";
    }
    std::string mag = prefix + digits;
    if (mag.empty()) mag = "0";
    return fmtPad(fmtApplySign(mag, neg, sp), sp, true);
}

inline std::string fmt(double v, const std::string& spec) {
    if (spec.empty()) return str(v);
    return fmtDouble(v, parseFmtSpec(spec));
}

// Everything that is not a plain double (ints, strings, bools, ...).
template <class T>
std::string fmt(const T& v, const std::string& spec) {
    if (spec.empty()) return str(v);
    FmtSpec sp = parseFmtSpec(spec);
    if constexpr (std::is_floating_point_v<T>) {
        return fmtDouble(static_cast<double>(v), sp);
    } else if constexpr (std::is_integral_v<T> && !std::is_same_v<std::remove_cv_t<T>, bool>) {
        return fmtIntegral(v, sp);
    } else {
        std::string body = str(v);
        if (sp.prec >= 0 && static_cast<long long>(body.size()) > sp.prec)
            body = body.substr(0, static_cast<std::size_t>(sp.prec));
        return fmtPad(body, sp, false);
    }
}

// ===================== random / time / math helpers =====================
inline std::mt19937_64& rng() {
    static std::mt19937_64 g(std::random_device{}());
    return g;
}
inline double random() {
    return std::uniform_real_distribution<double>(0.0, 1.0)(rng());
}
inline long long randint(long long a, long long b) {
    if (b < a) throw ValueError("empty range for randrange()");
    return std::uniform_int_distribution<long long>(a, b)(rng());
}
template <class T>
T choice(const std::vector<T>& v) {
    if (v.empty()) throw IndexError("cannot choose from an empty sequence");
    return v[static_cast<std::size_t>(std::uniform_int_distribution<long long>(
        0, static_cast<long long>(v.size()) - 1)(rng()))];
}
template <class T>
void shuffle(std::vector<T>& v) {
    std::shuffle(v.begin(), v.end(), rng());
}

inline long long factorial(long long n) {
    if (n < 0) throw ValueError("factorial() not defined for negative values");
    long long r = 1;
    for (long long i = 2; i <= n; ++i) r *= i;
    return r;
}
inline long long gcd_ll(long long a, long long b) {
    a = a < 0 ? -a : a;
    b = b < 0 ? -b : b;
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

inline double pi() { return 3.14159265358979323846; }
inline double e() { return 2.71828182845904523536; }
inline double inf() { return std::numeric_limits<double>::infinity(); }

// ---- tuple() --------------------------------------------------------------
// A Python tuple built from a runtime iterable has no static length, so it
// cannot become a std::tuple.  Wrap a vector in a distinct type that prints
// with parentheses and otherwise behaves like a sequence.
template <class T>
struct tup {
    std::vector<T> v;
    using value_type = T;
    std::size_t size() const { return v.size(); }
    bool empty() const { return v.empty(); }
    T& operator[](std::size_t i) { return v[i]; }
    const T& operator[](std::size_t i) const { return v[i]; }
    typename std::vector<T>::iterator begin() { return v.begin(); }
    typename std::vector<T>::iterator end() { return v.end(); }
    typename std::vector<T>::const_iterator begin() const { return v.begin(); }
    typename std::vector<T>::const_iterator end() const { return v.end(); }
};
template <class C>
auto to_tuple(const C& c) {
    tup<elem_t<C>> r;
    for (const auto& e : seq(c)) r.v.push_back(e);
    return r;
}
template <class T>
std::string str(const tup<T>& t) {
    std::string r = "(";
    for (std::size_t i = 0; i < t.v.size(); ++i) {
        if (i) r += ", ";
        r += repr(t.v[i]);
    }
    if (t.v.size() == 1) r += ",";
    return r + ")";
}
template <class T>
std::string repr(const tup<T>& t) {
    return str(t);
}

// Deferred definition of the generic repr: placed here so that it sees every
// str() overload declared above.
template <class T>
std::string repr(const T& v) {
    return str(v);
}

